    "hero.eyebrow": "ICT Competition · Environmental Education",
    "hero.title": 'OUR <span class="grad">ENVIRONMENT</span>',
    "hero.sub": "One Planet. One Home. One Responsibility.",
    "hero.text": "The environment is everything around us — the air we breathe, the water we drink, and the living world that shares our planet. Understanding it is the first step to protecting it.",
