  /* =========================================================
     HORIZONTAL SLIDES
     ========================================================= */
  (function(){
    const main=document.querySelector('main'),navEl=document.getElementById('nav'),foot=document.querySelector('.footer');
    main.appendChild(foot);
    const slides=[...main.children];
    slides.forEach((s,i)=>{const b=document.createElement('span');b.className='pnum';b.textContent='P-'+(i+1);s.appendChild(b)});
    const idx=()=>Math.round(main.scrollLeft/main.clientWidth);
    const go=i=>main.scrollTo({left:Math.max(0,Math.min(slides.length-1,i))*main.clientWidth,behavior:'smooth'});
    const dark=s=>s.classList.contains('hero')||s.classList.contains('section--dark')||s.id==='puzzle'||s===foot;
    const dots=document.createElement('div');dots.className='sdots';
    slides.forEach((s,i)=>{const d=document.createElement('i');d.onclick=()=>go(i);dots.appendChild(d)});document.body.appendChild(dots);
    [['l','‹',-1],['r','›',1]].forEach(([c,t,d])=>{const b=document.createElement('button');b.className='snav '+c;b.textContent=t;b.setAttribute('aria-label',d<0?'Previous':'Next');b.onclick=()=>go(idx()+d);document.body.appendChild(b)});
    function upd(){
      const i=idx(),s=slides[i];if(!s)return;
      navEl.classList.toggle('scrolled',!dark(s));
      document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('is-active',a.getAttribute('href')==='#'+s.id));
      [...dots.children].forEach((d,k)=>d.classList.toggle('on',k===i));
    }
    main.addEventListener('scroll',upd,{passive:true});upd();
    document.addEventListener('click',e=>{
      const a=e.target.closest('a[href^="#"]');if(!a)return;
      const k=slides.findIndex(s=>s.id===a.getAttribute('href').slice(1));
      if(k>-1){e.preventDefault();go(k)}
    });
    let lock=0;
    main.addEventListener('wheel',e=>{
      e.preventDefault();const n=Date.now();if(n-lock<750)return;
      const d=Math.abs(e.deltaY)>Math.abs(e.deltaX)?e.deltaY:e.deltaX;if(Math.abs(d)<10)return;lock=n;go(idx()+(d>0?1:-1));
    },{passive:false});
    document.addEventListener('keydown',e=>{
      if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
      if(['ArrowRight','PageDown'].includes(e.key))go(idx()+1);
      else if(['ArrowLeft','PageUp'].includes(e.key))go(idx()-1);
      else if(e.key==='Home')go(0);else if(e.key==='End')go(slides.length-1);
    });
    /* fit every slide inside the screen: shrink content slightly, never overlap */
    function fit(reset){
      const avail=innerHeight-78-36,W=Math.min(1200,innerWidth*.92);
      slides.forEach(s=>{
        const c=s.querySelector(':scope>.container');if(!c)return;
        if(reset)s._mh=0;
        c.style.transform='';c.style.width='';
        let h=Math.max(c.offsetHeight,s._mh||0),z=Math.max(.5,Math.min(1.12,avail/h));
        for(let k=0;k<5&&z!==1;k++){
          c.style.width=(W/z)+'px';h=Math.max(c.offsetHeight,s._mh||0);
          const nz=Math.max(.5,Math.min(1.12,avail/h));z=(z+nz)/2;
        }
        h=Math.max(c.offsetHeight,s._mh||0);z=Math.min(z,avail/h);
        s._mh=h;
        if(Math.abs(z-1)>.01)c.style.transform=`scale(${z})`;
      });
    }
    window.fitSlides=fit;
    addEventListener('resize',()=>{fit(true);go(idx())});
    document.addEventListener('click',()=>setTimeout(()=>fit(false),80));
    document.getElementById('langMenu').addEventListener('click',()=>setTimeout(()=>fit(true),120));
    (document.fonts&&document.fonts.ready||Promise.resolve()).then(()=>fit(true));
    setTimeout(()=>fit(true),400);
  })();

